// amzn-bl.js — Amazon Deep Dive ▸ Bottom Line ▸ General (BL-GEN-1…5) and Segments (BL-SEG), docs/PROFILE_PLAYBOOK.md §13.
//
// COPIED from js/overviews/googl-bl.js (itself meta-bl.js → tsm-bl.js → the dependency closure of the old amzn.js
// aMarginsBody · aBridgeBody · aNetBridgeBody · aSbcBody · expenseTabsBody · aBlFootGeneral · aBuildMargins ·
// aBuildExpenses · segmentsBody), then adapted to Amazon — never reimplemented:
//   • data: ./amzn-bbg.js (Bloomberg export, generated by scripts/bbg_extract.py) for the income statement and
//     consensus; ./amzn-bl-data.js for the reported functional expense lines, SBC by line and the segment rows
//     (10-K / 10-Q via SEC XBRL) and the expense-line and segment dives; ../results-data/amzn.js for the quarterly
//     operating-income and gross-profit series, segment revenue and operating income, and the Summit series.
//   • expense lines = Amazon's own (10-K "Operating expenses"): cost of sales — then fulfillment · technology and
//     infrastructure · sales and marketing · general and administrative · other operating expense (income), net. They
//     tie to operating income in every period. The 10-K gives cost of sales as one line (only its shipping-cost total is
//     disclosed), so it is ONE bar.
//   • cost of sales goes FIRST and apart in every bridge view, with a Gross profit subtotal (§13, SAB 2026-10-19), and
//     the bridge has the fourth mode "Cost structure" (stacked % of revenue over time).
//   • Consensus: Amazon's consensus revenue is the plain Bloomberg headline (no segment-sum override — Alphabet's TAC
//     problem does not exist here). Bloomberg carries no forward cost of sales, so the forward bridge derives it as
//     revenue − consensus gross profit; Bloomberg's other operating expense is income-positive and is sign-flipped.
//   • Normalized net income (as in the old amzn.js) = GAAP − other income (expense), net, after tax at the period's
//     effective rate — Amazon's GAAP earnings carry the marks on its equity investments (Rivian, then Anthropic). Net
//     interest stays in.
//   • Summit series: read from js/results-data/amzn.js, where the Summit DCF model is FROZEN (rule 10 — coded from the
//     dated snapshots, not live). Annual Summit comes from the dataset's annual rows only (never a sum of quarters); the
//     model has no cost of sales, gross profit or free cash flow, and its earnings line is its adjusted earnings
//     ("Model earnings (adj.)"). Summit diluted shares: the A_SUMMIT_SHARES block below, with its snapshot date.
//   • Amazon discloses SBC by income-statement line (10-K Note 8), so the SBC block offers Dilution | SBC by line.
//   • Segments: North America · International · AWS add up to consolidated operating income; Amazon discloses segment
//     D&A, so segment EBITDA (operating income + segment D&A) is drawn, and the segment cost bridge splits D&A from the
//     other operating expenses. When the forward segment bridge falls back from Summit to Bloomberg, the note says so.
//   • Annex A fixed in the copy: no typed years or labels (A12); shares axis on the RIGHT (A9); no inline <style>
//     (A1/A10; styles in css/overview.css under :is(.ov-tsm-dd, .ov-meta-dd, .ov-googl-dd, .ov-amzn-dd)); no hex colours
//     (Summit tokens from js/viz-palette.js); DOM lookups scoped to the Amazon root, not document.
import { SUMMIT_CAT, SUMMIT_INK, SUMMIT_MUTE, SUMMIT_POS, SUMMIT_NEG, fade } from '../viz-palette.js';
import { amznBBG } from './amzn-bbg.js';
import { amznResults } from '../results-data/amzn.js';
import { AMZN_OPEX_YEARS, AMZN_OPEX, AMZN_OPEXQ, AMZN_SBC_FN, AMZN_SBC_FN_SRC, AMZN_EW_LINES, AMZN_EW_SRC,
  AMZN_SEG_Y, AMZN_SEG_Q, AMZN_SEG_SRC, AMZN_SEG_ALLOC, AMZN_SEG_DIVES, AMZN_SEG_CAPEX, AMZN_SEG_PPE } from './amzn-bl-data.js';

var INK=SUMMIT_INK, MUTE=SUMMIT_MUTE, POS=SUMMIT_POS, NEG=SUMMIT_NEG, ONEOFF=SUMMIT_CAT[3];
var GRID='rgba(0,0,0,0.06)';
// amzn-bbg.js uses Amazon-native keys (the extractor's CODE map is Amazon-shaped), so no alias block is needed. Signs as
// exported: otherOpex and otherNonOp / netInterest / nonOpNet / equityMethod are EXPENSE-signed (a gain is negative).
// Summit diluted shares (M) — FROZEN, Summit DCF snapshot of Aug 4 2026 (the model holds them flat at the FY2025
// level). Carried over from the old amzn.js A_SUMMIT_SHARES; FY2027–FY2028 match amzn-target-multiple.js SNAP_DATA.
var A_SUMMIT_SHARES={ snap:'2026-08-04', y:{ 2026:10827, 2027:10827, 2028:10827 } };
function esc(s){ if(s==null) return ''; return String(s).replace(/&/g,'&').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
// ── DOM scope: everything is looked up inside the Amazon Deep Dive root (set by amznBlGeneralBuild), never document-wide.
var _root=null;
function R(){ return _root||document.querySelector('.ov-amzn-dd')||document; }
function $id(id){ return R().querySelector('#'+id); }
function aPane(){ return R().querySelector('.ovt-subpane[data-ovst="margins"]'); }
// Chart.js helpers (lazy: panes must be visible — offsetParent — before building).
var _aCharts={};
